    whyRu: 'Топовый знак из двух черных конусов, обращенных вершинами друг к другу, это западный кардинальный знак (znak kardynalny zachodni): безопасная вода лежит с западной стороны, значит обходить его надо с запада. При курсе на юг восток, где остается знак, приходится на левый борт, поэтому проходишь его левым бортом (lewą burtą).',
    source: 'baza CZ #230',
